sp_widget.client_script:
api.controller = function($scope, $location) {

    /* widget controller */

    var c = this;

    // Navigate to another Service Portal page
    c.goToPage = function(pageId) {

        if (!pageId) {
            return;
        }

        $location.search({
            id: pageId
        });

    };

};

sp_widget.css:
.claim-hub-modern {
    font-family: 'Inter', 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    color: #2c3e50;
    background-color: #f8f9fa;
    padding-bottom: 40px;
}

/* Hero Section */
.hero-section {
    background: linear-gradient(135deg, #0757b8 0%, #124c9b 100%);
    padding: 80px 20px 100px 20px;
    color: #ffffff;
    border-radius: 0 0 30px 30px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

.hero-badge {
    display: inline-block;
    background: rgba(255, 255, 255, 0.15);
    padding: 8px 16px;
    border-radius: 20px;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 1px;
    text-transform: uppercase;
    margin-bottom: 20px;
    border: 1px solid rgba(255, 255, 255, 0.3);
}

.hero-title {
    font-size: 42px;
    font-weight: 700;
    margin-bottom: 20px;
}

.hero-subtitle {
    font-size: 18px;
    max-width: 700px;
    margin: 0 auto 35px auto;
    opacity: 0.9;
    line-height: 1.6;
}

/* Buttons */
.custom-btn {
    border-radius: 30px;
    padding: 12px 30px;
    font-size: 16px;
    font-weight: 600;
    border: none;
    transition: all 0.3s ease;
    margin: 5px;
}

.custom-btn-primary {
    background: #ffffff;
    color: #0757b8;
    box-shadow: 0 4px 15px rgba(0,0,0,0.1);
}

.custom-btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(0,0,0,0.2);
    color: #0757b8;
}

.custom-btn-outline {
    background: transparent;
    color: #ffffff;
    border: 2px solid #ffffff;
}

.custom-btn-outline:hover {
    background: #ffffff;
    color: #0757b8;
}

/* Overlapping Quick Actions */
.quick-actions-section {
    position: relative;
    margin-top: -60px; /* Pulls cards up over the hero banner */
    z-index: 10;
    padding: 0 20px;
}

.glass-card {
    background: #ffffff;
    border-radius: 16px;
    padding: 30px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.08);
    transition: all 0.3s ease;
    cursor: pointer;
    margin-bottom: 20px;
    border: 1px solid #edf2f7;
    height: calc(100% - 20px);
}

.glass-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 20px 40px rgba(0,0,0,0.12);
    border-color: #cbd5e0;
}

.card-icon {
    width: 60px;
    height: 60px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 24px;
    color: #ffffff;
    margin-bottom: 20px;
    box-shadow: 0 4px 10px rgba(0,0,0,0.1);
}

.bg-blue { background: linear-gradient(135deg, #4299e1, #3182ce); }
.bg-green { background: linear-gradient(135deg, #48bb78, #38a169); }
.bg-purple { background: linear-gradient(135deg, #9f7aea, #805ad5); }

.glass-card h3 {
    font-size: 22px;
    font-weight: 600;
    margin-top: 0;
    margin-bottom: 12px;
    color: #173b6c;
}

.glass-card p {
    color: #687386;
    font-size: 15px;
    line-height: 1.6;
    margin-bottom: 20px;
}

.card-link {
    color: #3182ce;
    font-weight: 600;
    font-size: 15px;
    display: flex;
    align-items: center;
    gap: 5px;
    transition: gap 0.2s;
}

.glass-card:hover .card-link {
    gap: 10px;
}

/* Features Section */
.features-section {
    padding: 80px 20px 40px 20px;
}

.section-header {
    margin-bottom: 40px;
}

.small-title {
    color: #3182ce;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2px;
}

.section-header h2 {
    font-size: 32px;
    font-weight: 700;
    color: #173b6c;
    margin-top: 10px;
}

.feature-pill {
    text-align: center;
    padding: 20px;
}

.feature-pill i {
    font-size: 40px;
    color: #3182ce;
    margin-bottom: 20px;
    opacity: 0.9;
}

.feature-pill h4 {
    font-weight: 600;
    font-size: 18px;
    color: #173b6c;
}

.feature-pill p {
    color: #687386;
    font-size: 14px;
}

sp_widget.script:
(function() {
    data.portal_name = "Insurance Claim Hub";
    data.tagline = "Secure Claims. Smarter Tomorrow.";
})();
